"""Minimal P2 words (newest first, True=A) generated by DFS with feasibility pruning; cached to pickle."""
import pickle, os, sys
from functools import lru_cache
def gen(L):
    out=[]
    w=[False]*L
    def feasible(d,m,mu):
        r=L-d
        if r==0: return m==1 and mu==0
        twoa=1-m+r
        if twoa<0 or twoa%2 or twoa>2*r: return False
        a=twoa//2
        pos=list(range(d+1,L+1))
        tot=sum(pos)
        # moment of remainder = 2*sum(A positions) - tot
        mn=2*sum(pos[:a])-tot; mx=2*sum(pos[r-a:])-tot
        return mn<=-mu<=mx
    def rec(d,m,mu):
        if d==L:
            if m==1 and mu==0: out.append(tuple(w))
            return
        if d>0 and m==1 and mu==0: return  # proper prefix P2 -> not minimal
        for b in (True,False):
            m2=m+(1 if b else -1); mu2=mu+(d+1)*(1 if b else -1)
            if feasible(d+1,m2,mu2):
                w[d]=b; rec(d+1,m2,mu2)
    rec(0,0,0)
    return out
@lru_cache(None)
def minimal_words(L):
    fn=f'mw_{L}.pkl'
    if os.path.exists(fn): return pickle.load(open(fn,'rb'))
    ws=gen(L); pickle.dump(ws,open(fn,'wb')); return ws
def s(w): return ''.join('A' if b else 'S' for b in w)
def parse(t): return tuple(c=='A' for c in t)
def heights(w):
    """relative walk H(j)=F(t+j)-h for j=0..L, t=b-L oldest clock.  w newest first."""
    L=len(w); H=[0]
    for j in range(L):  # clock t+j has letter w_{L-j}
        H.append(H[-1]+(1 if w[L-1-j] else -1))
    return H
if __name__=='__main__':
    for L in range(3,int(sys.argv[1])+1,4):
        ws=minimal_words(L); print(L,len(ws))
